INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 0, "お！\nあそこに困ってそうな人発見！", 0, 1, 0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 2, 1001, "春咲 ひより", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "わ、わたし、\nなに言ってるんだろ\nあはは…", 0, "大切な人を\n守れるようになりたい…って", 0, 1, 0, "みんなみたいに\nわたしも強くならなきゃ", 2, 1002, "草野 優衣", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "少しは磨かれると思いますよ。", 0, "キミに必要な集中力と感性が", 0, 1, 0, "フェンシングを始めてみては？", 2, 1003, "士条 怜", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "みそぎはねぇ、\nかくれんぼやりたい！", 0, "今日はなにして遊ぶ？", 0, 1, 0, "ねぇ、にいちゃん！", 2, 1004, "穂高 みそぎ", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "私といっしょに…\nいかない？", 0, "ねぇ…", 0, 1, 0, "風宮あかりです", 2, 1006, "風宮 あかり", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "食べ物の恨みは怖いのー", 0, "プリンたべたいのー", 0, 1, 0, "出雲宮子なのー", 2, 1007, "出雲 宮子", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "いいよ。\n見られることは運命さ…", 0, "キミもボクの美貌に\n吸い寄せられたんだね。", 0, 1, 0, "ボクは虹村雪。", 2, 1008, "虹村 雪", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "人呼んで「疾風の冥姫」!!", 0, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, 1, 0, "フッ…聞いて後悔するがいい！", 2, 1009, "柊杏奈", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "ほんまおおきにやわ～♪", 0, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, 1, 0, "マホマホ王国のプリンセス、\nまほ姫どす", 2, 1010, "姫宮 真歩", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "ここで会ったが\n100年目～！", 0, "生き別れたお兄ちゃんを探して\n三千世界！", 0, 1, 0, "衣之咲璃乃です！", 2, 1011, "衣之咲 璃乃", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "…って、お願い！\n誰にも言わないでおいて～！", 0, "ち、超能力って…\n何のことかな～？", 0, 1, 0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 2, 1012, "柏崎 初音", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 0, "一応カリスマ読モJKやってまっす！", 0, 1, 0, "ちょす！\n美波鈴奈だよ～♪", 2, 1016, "美波 鈴奈", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "でも、沖縄もとってもいいとこさー", 0, "東京は遊園地みたいなところさー", 0, 1, 0, "はいたーい。\n喜屋武香織さー。", 2, 1017, "喜屋武 香織", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "イオちゃんって呼んでね。", 0, "先生って呼ばれるのは\nくすぐったいから", 0, 1, 0, "支倉伊緒です。", 2, 1018, "支倉 伊緒", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "ミミをおいてかないでぇ～", 0, "あ！/\お兄ちゃ～ん\nまってよ～", 0, 1, 0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 2, 1020, "茜 ミミ", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "ふぇぇぇぇぇん……", 0, "あの……\nふぇ……", 0, 1, 0, "あ…あの…えっと…\n栗…林…くるみ…です……", 2, 1021, "栗林 くるみ", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "なんてありがとうございます！", 0, "こんな私に貴重な時間を\n割いていただき、", 0, 1, 0, "風宮よりです。\nあああああ！", 2, 1022, "風宮 より", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "私こっち行きたいー\nね、早く早くー", 0, "おにいちゃんどこいくの？\nえ？", 0, 1, 0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 2, 1023, "北条 綾音", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "これて何か違う…\nあああすみません！", 0, "ふ、不束者ですが\nどうぞ末永く…って、", 0, 1, 0, "わっ…わっ…私、\n天野すずめといいます！", 2, 1025, "天野 すずめ", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "離しませんわ………\n絶対に…!!", 0, "あなたは…運命の……\n伴侶……", 0, 1, 0, "……クスクス…私は\n…倉石恵理子……", 2, 1027, "倉石 恵理子", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "…そうでしょ？？", 0, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, 1, 0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 2, 1028, "佐々木 咲恋", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "あはは、\n私もまだまだだなぁ～", 0, "ぇっと…\nキミ、私のこと知らないの?!", 0, 1, 0, "桜井望だよ！\nよろしくねっ", 2, 1029, "桜井 望", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "ショーグン、\nワタシと一緒に天下統一デース！", 0, "初めまして、\n私はニノン・ジュベール申すデス！", 0, 1, 0, "デケデケデンっ！", 2, 1030, "ニノン・ジュベール", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "おかしいですね……", 0, "でもって私の隣にいるのが……\nえ、見えない？", 0, 1, 0, "上喜しのぶです。\n手元のドクロが父です。", 2, 1031, "上喜 しのぶ", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "そう、\nオラのボケに突っ込める相方が…！", 0, "けんども\nそれには足りないモンが…", 0, 1, 0, "目指すはビッグな\nお笑い芸人だっぺ！", 2, 1033, "野戸まひる", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "ちょ\nちょっと一杯飲んできます…！", 0, "ちょっと緊張しちゃって…", 0, 1, 0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 2, 1034, "綾瀬 ゆかり", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "これ以上お話しすることは…\nないです！", 0, "知らない人とは話しちゃいけないので", 0, 1, 0, "氷川鏡華…です", 2, 1036, "氷川 鏡華", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 0, "……あ、アラーム。", 0, 1, 0, "柏崎…栞です。", 2, 1038, "柏崎 栞", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "野に咲く花が、\n唯一の話相手です。", 0, "私、一人も友達がいなくて……", 0, 1, 0, "ふ、双葉碧です。", 2, 1040, "双葉 碧", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "そう思っています。", 0, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, 1, 0, "三角千歌です。", 2, 1042, "三角 千歌", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "う、疑ってすまなかったな…", 0, "あぁ？\nお前のそいつの仲間か？", 0, 1, 0, "安芸真琴だ。", 2, 1043, "安芸 真琴", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 0, "生けとし生ける全ての者よ！", 0, 1, 0, "わらわこそは夜を総べる者！", 2, 1044, "イリヤ・オーンスタイン", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "ｌク、クウカに何かご用ですか!?", 0, "ぐふふふふ……はっ！", 0, 1, 0, "そこで騎士は妖精を乱暴に……", 2, 1045, "遠見 空花", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "う～ん…\n猫ってホントに最高にゃ～♪", 0, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, 1, 0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 2, 1046, "宮坂たまき", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 0, "それでは早速クエストに…", 0, 1, 0, "大神美冬よ！", 2, 1048, "大神 美冬", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 0, "クエストもバトルも\n掃除も洗濯も", 0, 1, 0, "星野静流だよ！", 2, 1049, "星野静流", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 0, "見ての通りの\nセクシー美少女で", 0, 1, 0, "アタシは玉泉美咲。", 2, 1050, "玉泉美咲", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.4, "？？？？", 0, "？？？？", 0, 1, 0, "？？？", 2, 1052, "リマ", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "そ、そこまでいうなら\nもらってやる", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1, 0, "モニカ・ヴァイスヴィントだ。", 2, 1053, "モニカ・ヴァイスヴィント", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "そ、そこまでいうなら\nもらってやる", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1, 0, "モニカ・ヴァイスヴィントだ。", 2, 1058, "ペコリーヌ", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "そ、そこまでいうなら\nもらってやる", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1, 0, "モニカ・ヴァイスヴィントだ。", 2, 1059, "コッコロ", 0, 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 1.5, "そ、そこまでいうなら\nもらってやる", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1, 0, "モニカ・ヴァイスヴィントだ。", 2, 1060, "キャル", 0, 1, 1);
